import { lerp, clamp, ease } from "./helpers";

export const RX = 32;
export const RY = 24;

export default function HeroCard({ card, progress, vw }) {
  /*
   * Orbit radii — increased for more horizontal + vertical spread.
   * Was 32/24 → now 40/30 on desktop.
   */
  const rx = vw >= 1024 ? 40 : vw >= 600 ? 30 : 34;
  const ry = vw >= 1024 ? 30 : vw >= 600 ? 22 : 26;

  const cardWidth  = vw >= 1024 ? 190 : vw >= 600 ? 142 : 156;
  const cardHeight = vw >= 1024 ? 234 : vw >= 600 ? 175 : 192;
  const borderRad  = vw >= 1024 ? 20  : 13;

  /*
   * explodeDist increased significantly for wider final spread.
   * Was 148 → now 172 on desktop, proportionally on other breakpoints.
   */
  const explodeDist = vw >= 1024 ? 172 : vw >= 600 ? 126 : 136;

  const rad = (card.angle * Math.PI) / 180;
  const ox  = Math.cos(rad) * rx;
  const oy  = -Math.sin(rad) * ry;
  const mag = Math.sqrt(ox * ox + oy * oy) || 1;
  const EX  = (ox / mag) * explodeDist;
  const EY  = (oy / mag) * explodeDist;

  const t       = ease(clamp((progress - 0.35) / 0.55, 0, 1));
  const tx      = lerp(ox, EX, t);
  const ty      = lerp(oy, EY, t);
  const opacity = lerp(1, 0, clamp((progress - 0.65) / 0.3, 0, 1));

  /*
   * Shadow direction derived from card angle so each card feels
   * lit from the center — cards on the left cast shadows left,
   * cards on top cast shadows upward, etc.
   * This gives the cluster a coherent 3-D light-source feel.
   */
  const shadowX = +(Math.cos(rad) * 6).toFixed(1);
  const shadowY = -(Math.sin(rad) * 6).toFixed(1);
  const shadow  = `${shadowX}px ${shadowY}px 28px rgba(0,0,0,0.55),
                   ${shadowX * 0.4}px ${shadowY * 0.4}px 10px rgba(0,0,0,0.35)`;

  return (
    <div
      style={{
        position: "absolute",
        left: `calc(50% + ${tx}vw)`,
        top: `calc(50% + ${ty}vh)`,
        /*
         * rotate comes from card data (already varied per card).
         * Added a subtle perspective-tilt via rotateX/rotateY to push
         * each card slightly toward/away from viewer based on its orbit position.
         * Cards near top tilt forward (positive rotateX), bottom tilt back.
         */
        transform: `
          translate(-50%, -50%)
          perspective(800px)
          rotate(${card.rotate}deg)
          rotateX(${(Math.sin(rad) * 6).toFixed(1)}deg)
          rotateY(${-(Math.cos(rad) * 4).toFixed(1)}deg)
        `,
        opacity,
        zIndex: card.z,
        willChange: "transform, opacity",
        pointerEvents: "none",
        /*
         * Drop shadow applied at wrapper level so it renders outside
         * the card's overflow:hidden boundary — looks correct on rotated cards.
         */
        filter: `drop-shadow(${shadowX}px ${shadowY}px 18px rgba(0,0,0,0.60))
                 drop-shadow(0px 4px 8px rgba(0,0,0,0.30))`,
      }}
    >
      <div
        style={{
          width: cardWidth,
          height: cardHeight,
          borderRadius: borderRad,
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          position: "relative",
          /*
           * Inner box-shadow for a soft card-edge glow so cards
           * don't feel flat against the dark background.
           */
          boxShadow: "inset 0 0 0 1px rgba(255,255,255,0.10)",
        }}
      >
        <div style={{ flex: 1, position: "relative", overflow: "hidden" }}>
          <img
            src={`/assets/img${card.id}.png`}
            alt=""
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              display: "block",
            }}
          />
        </div>
      </div>
    </div>
  );
}
